changeSet.sql:
ALTER TABLE modeling_model_spec
    ADD CONSTRAINT ck_model_spec_v2_type_context
    CHECK (
        contract_version <> 2 OR (
            (model_type = 'FACT' OR business_activity_ref IS NULL)
            AND (
                model_type <> 'APPLICATION'
                OR status = 'DRAFT'
                OR (
                    consumption_scenario IS NOT NULL
                    AND btrim(consumption_scenario) <> ''
                )
            )
            AND (model_type = 'APPLICATION' OR consumption_scenario IS NULL)
            AND (
                fact_shape IS NULL
                OR fact_shape IN ('TRANSACTION', 'PERIODIC_SNAPSHOT', 'ACCUMULATING_SNAPSHOT')
            )
        )
    );

rollback.sql:
DO $$
BEGIN
    RAISE EXCEPTION 'ROLLBACK_BLOCKED_MODEL_SPEC_LIGHTWEIGHT_DRAFT_FORWARD_ONLY: Existing application drafts may not have a consumption scenario';
END $$;
